def transform(grid):
    """Restore 6-valued occlusions using the grid's diagonal and horizontal symmetries."""
    n = len(grid)
    out = [row[:] for row in grid]
    for r in range(n):
        for c in range(n):
            if grid[r][c] != 6:
                continue
            seen = {(r, c)}
            todo = [(r, c)]
            value = None
            while todo:
                a, b = todo.pop(0)
                if grid[a][b] != 6:
                    value = grid[a][b]
                    break
                neighbors = [(b, a)]
                if 2 <= a <= 29:
                    neighbors.append((31 - a, b))
                for p in neighbors:
                    if 0 <= p[0] < n and 0 <= p[1] < n and p not in seen:
                        seen.add(p)
                        todo.append(p)
            if value is not None:
                out[r][c] = value
    return out
